import type * as D from './types.d.ts'

export interface Definitions {
  service: D.DefinitionsService
  network: D.DefinitionsNetwork
  volume: D.DefinitionsVolume
  secret: D.DefinitionsSecret
  config: D.DefinitionsConfig
}

type DefInit<T, C> = T | ((c: C) => T) | ((c: C) => Promise<T>)

export type Context<N extends string> = {
  name: N
  build?: boolean
}

export interface ResourceDef {
  type: keyof Definitions
  name: string
  init: () => Promise<any>
}

const resorce =
  <S extends keyof Definitions>(type: S) =>
  <N extends string, const T extends Definitions[S]>(name: N, def: DefInit<T, Context<N>>) => {
    const init = async () => (typeof def !== 'function' ? def : await def({ name }))
    return { type, name, init }
  }

export const Service = resorce('service')

export const Network = resorce('network')

export const Volume = resorce('volume')

export const Secret = resorce('secret')

export const Config = resorce('config')

export const Var = <N extends string, T>(name: N) => {
  const provide = (value: T) => registry().set(name, value)
  const get = () => {
    if (registry().has(name)) return registry().get(name)
    throw new Error(`Var ${name} not found`)
  }
  return { name, provide, get }
}

let reg: Map<string, any> | undefined
const registry = () => {
  if (reg === undefined) reg = new Map()
  return reg
}
